-- Lösungswege für die Forderungskarte (ohne Punkte). Upsert, damit gespeicherte Forderungen ihren Verweis behalten.
insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft) values
  (10838, 44, 'Neue EU-Freihandelsabkommen mit Drittstaaten zügig abschließen und Absatzmärkte diversifizieren (Bund)', 'Modellrechnungen (ifo 2025) zeigen, dass Abkommen u. a. mit Mercosur, Indien und ASEAN-Staaten die Exportverluste durch US-Zölle ausgleichen könnten; Zollsätze der USA ändern sie nicht. Abschluss liegt bei der EU und braucht Zustimmung der Partner.', 'gemischt', null, 'bund', null, true, 'blind'),
  (10839, 44, 'Mit den USA über Abbau von Zöllen und Handelshemmnissen verhandeln, etwa sektorale Abkommen (Bund)', 'Setzt direkt an den US-Zöllen an; ein Industriezoll-Abkommen würde Exporte entlasten. Ergebnis hängt vom Willen der US-Regierung ab, Handelspolitik ist EU-Zuständigkeit; die Verhandlungen 2025 brachten nur begrenzte Senkungen.', 'offen', null, 'bund', null, true, 'blind'),
  (10840, 44, 'Rohstoffpartnerschaften und Abkommen zur Diversifizierung der Rohstoffbezugsquellen (Bund)', 'Japan senkte nach 2010 mit Partnerschaften und staatlich gestützten Investitionen seine Abhängigkeit von China bei Seltenen Erden von über 90 auf 60–70 %. Partnerschaften ohne Finanzierung brachten in Deutschland bisher kaum Lieferungen.', 'gemischt', 'https://thenightly.com.au/politics/world/the-new-york-times-how-japan-built-a-rare-earth-supply-chain-without-china-c-20939714', 'bund', null, true, 'blind'),
  (10841, 44, 'Heimischen und europäischen Rohstoffabbau durch modernisiertes Bergrecht und schnellere Verfahren stärken (Bund)', 'Mehr eigene Förderung verringert Importabhängigkeit; neue Bergwerke brauchen aber im Schnitt weit über zehn Jahre bis zur Produktion, und für viele kritische Rohstoffe fehlen in Deutschland abbauwürdige Vorkommen.', 'offen', null, 'bund', null, true, 'blind'),
  (10842, 44, 'Recycling und Kreislaufwirtschaft fördern, Recycling- und Einsatzquoten erhöhen (Bund)', 'Recycling ersetzt langfristig Primärrohstoffe; bei Seltenen Erden liegt die Recyclingquote aber nur bei etwa 1 %, und Rückläufe aus langlebigen Produkten kommen spät. Quoten sind teils EU-rechtlich vorgeprägt.', 'belegt', 'https://www.jyu.fi/en/news/towards-better-autonomy-rare-earth-elements-recycled-from-waste', 'bund', null, true, 'blind'),
  (10843, 44, 'Gegen zollfreie Billigsendungen und unsichere Produkte aus Drittstaaten vorgehen, Zollkontrollen verschärfen (Bund)', 'Schließt Lücken, über die Kleinsendungen zoll- und kontrollfrei hereinkommen; die EU hat die Abschaffung der 150-Euro-Freigrenze beschlossen. Der Effekt auf heimische Hersteller ist kaum untersucht; Händler weichen etwa auf EU-Lager aus.', 'offen', null, 'bund', null, true, 'blind'),
  (10844, 44, 'EU-Handelsschutz nutzen: Antisubventions- und Antidumpingverfahren, Ausgleichszölle (Bund)', 'Antidumpingzölle senken Einfuhren aus China deutlich (Felbermayr/Sandkamp), helfen aber vor allem schwächeren Herstellern und schaden Weiterverarbeitern; Nettoeffekt auf Beschäftigung eher negativ. Verfahren führt die EU-Kommission.', 'gemischt', 'https://www.ifo.de/en/cesifo/publications/2018/working-paper/trade-effects-anti-dumping-duties-firm-level-evidence-china', 'bund', null, true, 'blind'),
  (10845, 44, 'CO₂-Grenzausgleich (CBAM) nachbessern: Anwendungsbereich, Verfahren, Exportentlastung (Bund)', 'Ein wirksamerer CBAM gleicht CO₂-Kosten bei Importen von Stahl, Zement u. a. aus und mindert Wettbewerbsnachteile; er betrifft nur wenige Branchen, Studien sehen Lücken bei Weiterverarbeitern. Änderung liegt bei der EU.', 'gemischt', null, 'bund', null, true, 'blind')
on conflict (id) do update set thema_id = excluded.thema_id, name = excluded.name, begruendung = excluded.begruendung,
  evidenz = excluded.evidenz, beleg_studie_url = excluded.beleg_studie_url, ebene = excluded.ebene,
  entspricht = excluded.entspricht, ki_entwurf = excluded.ki_entwurf, entwurf_herkunft = excluded.entwurf_herkunft;

