insert into public.massnahmen (id, thema_id, partei_id, land, beschreibung, ursachen_ids, instrument_id, wirksamkeit, umsetzbarkeit,
  rollen_modifikator, begruendung, beleg_programm_url, beleg_studie_url, evidenz, stand, geprueft, ki_entwurf, entwurf_herkunft) values
  (10846, 44, 11, null, 'Mercosur-Abkommen zügig in Kraft setzen', '{4401}', 10838, 2, 1, null, 'Modellrechnungen (ifo 2025) zeigen, dass Abkommen u. a. mit Mercosur, Indien und ASEAN-Staaten die Exportverluste durch US-Zölle ausgleichen könnten; Zollsätze der USA ändern sie nicht. Abschluss liegt bei der EU und braucht Zustimmung der Partner.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=20', null, 'gemischt', '2026-10-22', false, true, 'blind'),
  (10847, 44, 11, null, 'Neue Handelsabkommen in der EU unterstützen und die Partnerschaft mit den USA zu einem transatlantischen Handelsraum vertiefen', '{4401}', 10839, 2, 1, null, 'Setzt direkt an den US-Zöllen an; ein Industriezoll-Abkommen würde Exporte entlasten. Ergebnis hängt vom Willen der US-Regierung ab, Handelspolitik ist EU-Zuständigkeit; die Verhandlungen 2025 brachten nur begrenzte Senkungen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=20', null, 'offen', '2026-10-22', false, true, 'blind'),
  (10848, 44, 11, null, 'Bei marktverzerrenden Subventionen das EU-Antisubventionsverfahren und einen WTO-Streitschlichtungsmechanismus nutzen', '{4403}', 10844, 2, 1, null, 'Antidumpingzölle senken Einfuhren aus China deutlich (Felbermayr/Sandkamp), helfen aber vor allem schwächeren Herstellern und schaden Weiterverarbeitern; Nettoeffekt auf Beschäftigung eher negativ. Verfahren führt die EU-Kommission.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=20', 'https://www.ifo.de/en/cesifo/publications/2018/working-paper/trade-effects-anti-dumping-duties-firm-level-evidence-china', 'gemischt', '2026-10-22', false, true, 'blind'),
  (10849, 44, 11, null, 'Kritische Abhängigkeiten bei Absatzmärkten, Rohstoffquellen und Lieferketten verringern, durch stärkere Diversifizierung', '{4402}', 10840, 2, 2, null, 'Japan senkte nach 2010 mit Partnerschaften und staatlich gestützten Investitionen seine Abhängigkeit von China bei Seltenen Erden von über 90 auf 60–70 %. Partnerschaften ohne Finanzierung brachten in Deutschland bisher kaum Lieferungen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=20', 'https://thenightly.com.au/politics/world/the-new-york-times-how-japan-built-a-rare-earth-supply-chain-without-china-c-20939714', 'gemischt', '2026-10-22', false, true, 'blind'),
  (10850, 44, 11, null, 'Versorgung durch heimischen Rohstoffabbau sichern und Wertstoffe aus Recycling als Rohstoffe nutzen', '{4402}', 10841, 1, 2, null, 'Mehr eigene Förderung verringert Importabhängigkeit; neue Bergwerke brauchen aber im Schnitt weit über zehn Jahre bis zur Produktion, und für viele kritische Rohstoffe fehlen in Deutschland abbauwürdige Vorkommen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=20', null, 'offen', '2026-10-22', false, true, 'blind'),
  (10851, 44, 11, null, 'Vorratshaltung von Rohstoffen über eine Bevorratungsrücklage anreizen', '{4402}', null, 2, 2, null, 'Vorräte überbrücken Lieferstopps bei Exportbeschränkungen direkt; Japan betreibt ein solches System seit Jahren. Wirkungen sind kaum evaluiert, Vorräte lösen die Abhängigkeit nicht, und die steuerliche Rücklage kostet Einnahmen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=20', null, 'offen', '2026-10-22', false, true, 'blind'),
  (10852, 44, 12, null, 'Handelshemmnisse gegenüber den USA abbauen und einen Subventionswettlauf vermeiden.', '{4401}', 10839, 2, 1, null, 'Setzt direkt an den US-Zöllen an; ein Industriezoll-Abkommen würde Exporte entlasten. Ergebnis hängt vom Willen der US-Regierung ab, Handelspolitik ist EU-Zuständigkeit; die Verhandlungen 2025 brachten nur begrenzte Senkungen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=61', null, 'offen', '2026-10-22', false, true, 'blind'),
  (10853, 44, 12, null, 'Handelsabkommen schneller abschließen; Entscheidung im Ministerrat mit qualifizierter Mehrheit statt Einstimmigkeit.', '{4401}', 10838, 2, 1, null, 'Modellrechnungen (ifo 2025) zeigen, dass Abkommen u. a. mit Mercosur, Indien und ASEAN-Staaten die Exportverluste durch US-Zölle ausgleichen könnten; Zollsätze der USA ändern sie nicht. Abschluss liegt bei der EU und braucht Zustimmung der Partner.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=65', null, 'gemischt', '2026-10-22', false, true, 'blind'),
  (10854, 44, 12, null, 'Rohstofffonds schaffen und die heimische Rohstoffgewinnung ausbauen.', '{4402}', null, 2, 3, null, 'Ein staatlicher Rohstofffonds kann wie in Japan Projekte außerhalb Chinas mitfinanzieren und Abhängigkeit spürbar senken; der Fonds besteht bereits. Heimische Förderung wirkt erst nach vielen Jahren.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=11', 'https://thenightly.com.au/politics/world/the-new-york-times-how-japan-built-a-rare-earth-supply-chain-without-china-c-20939714', 'belegt', '2026-10-22', false, true, 'blind'),
  (10855, 44, 12, null, 'Europäische Resilienzstrategie gegen Lieferrisiken (De-Risking) und Abhängigkeiten bei Rohstoffen und Vorprodukten.', '{4402}', null, 1, 1, null, 'Eine EU-Resilienzstrategie kann Abhängigkeiten bei Rohstoffen und Vorprodukten verringern; der Text bleibt ohne konkrete Instrumente, und die Umsetzung hängt von EU-Entscheidungen ab.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=11', null, 'offen', '2026-10-22', false, true, 'blind'),
  (10856, 44, 12, null, 'Mit strategischen Partnerschaften und Allianzen den Zugang zu wertvollen Rohstoffen sichern.', '{4402}', 10840, 2, 2, null, 'Japan senkte nach 2010 mit Partnerschaften und staatlich gestützten Investitionen seine Abhängigkeit von China bei Seltenen Erden von über 90 auf 60–70 %. Partnerschaften ohne Finanzierung brachten in Deutschland bisher kaum Lieferungen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=64', 'https://thenightly.com.au/politics/world/the-new-york-times-how-japan-built-a-rare-earth-supply-chain-without-china-c-20939714', 'gemischt', '2026-10-22', false, true, 'blind'),
  (10857, 44, 12, null, 'CO2-Grenzausgleichsmechanismus für Importe entbürokratisieren und um Exportförderung ergänzen.', '{4403}', 10845, 1, 1, null, 'Ein wirksamerer CBAM gleicht CO₂-Kosten bei Importen von Stahl, Zement u. a. aus und mindert Wettbewerbsnachteile; er betrifft nur wenige Branchen, Studien sehen Lücken bei Weiterverarbeitern. Änderung liegt bei der EU.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=11', null, 'gemischt', '2026-10-22', false, true, 'blind'),
  (10858, 44, 13, null, 'Neue Rohstoffpartnerschaften schließen, die auf Menschenrechte und Umweltschutz ausgerichtet sind.', '{4402}', 10840, 2, 2, null, 'Japan senkte nach 2010 mit Partnerschaften und staatlich gestützten Investitionen seine Abhängigkeit von China bei Seltenen Erden von über 90 auf 60–70 %. Partnerschaften ohne Finanzierung brachten in Deutschland bisher kaum Lieferungen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=30', 'https://thenightly.com.au/politics/world/the-new-york-times-how-japan-built-a-rare-earth-supply-chain-without-china-c-20939714', 'gemischt', '2026-10-22', false, true, 'blind'),
  (10859, 44, 13, null, 'Heimischen und europäischen Rohstoffabbau mit modernisiertem Bergrecht und schnelleren Verfahren fördern.', '{4402}', 10841, 1, 2, null, 'Mehr eigene Förderung verringert Importabhängigkeit; neue Bergwerke brauchen aber im Schnitt weit über zehn Jahre bis zur Produktion, und für viele kritische Rohstoffe fehlen in Deutschland abbauwürdige Vorkommen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=30', null, 'offen', '2026-10-22', false, true, 'blind'),
  (10860, 44, 13, null, 'Abfallvermeidung, Wiederverwendung und Recycling für eine Kreislaufwirtschaft fördern.', '{4402}', 10842, 1, 2, null, 'Recycling ersetzt langfristig Primärrohstoffe; bei Seltenen Erden liegt die Recyclingquote aber nur bei etwa 1 %, und Rückläufe aus langlebigen Produkten kommen spät. Quoten sind teils EU-rechtlich vorgeprägt.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=30', 'https://www.jyu.fi/en/news/towards-better-autonomy-rare-earth-elements-recycled-from-waste', 'belegt', '2026-10-22', false, true, 'blind'),
  (10861, 44, 13, null, 'Bei Ausschreibungen in abhängigen Sektoren Resilienzvorgaben des Net-Zero Industry Act anwenden.', '{4402}', null, 1, 3, null, 'Resilienzkriterien in Ausschreibungen (etwa Wind, Solar) mindern die Abhängigkeit von einzelnen Lieferländern bei Vorprodukten; die EU-Vorgaben gelten bereits, die Wirkung ist noch nicht untersucht und kann Kosten erhöhen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=30', null, 'offen', '2026-10-22', false, true, 'blind'),
  (10862, 44, 13, null, 'Ausgleichszölle auf EU-Ebene unterstützen, wo unfaire Handelspraktiken geboten sind, etwa auf Stahl.', '{4403}', 10844, 2, 1, null, 'Antidumpingzölle senken Einfuhren aus China deutlich (Felbermayr/Sandkamp), helfen aber vor allem schwächeren Herstellern und schaden Weiterverarbeitern; Nettoeffekt auf Beschäftigung eher negativ. Verfahren führt die EU-Kommission.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=29', 'https://www.ifo.de/en/cesifo/publications/2018/working-paper/trade-effects-anti-dumping-duties-firm-level-evidence-china', 'gemischt', '2026-10-22', false, true, 'blind'),
  (10863, 44, 13, null, 'Zollschlupflöcher schließen, durch die Onlinehändler unsichere Produkte am Zoll vorbeischleusen.', '{4403}', 10843, 1, 2, null, 'Schließt Lücken, über die Kleinsendungen zoll- und kontrollfrei hereinkommen; die EU hat die Abschaffung der 150-Euro-Freigrenze beschlossen. Der Effekt auf heimische Hersteller ist kaum untersucht; Händler weichen etwa auf EU-Lager aus.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=29', null, 'offen', '2026-10-22', false, true, 'blind'),
  (10864, 44, 13, null, 'CO₂-Grenzausgleich CBAM praxistauglicher und wirksamer gestalten, gegen Wettbewerbsnachteile europäischer Industrie.', '{4403}', 10845, 1, 1, null, 'Ein wirksamerer CBAM gleicht CO₂-Kosten bei Importen von Stahl, Zement u. a. aus und mindert Wettbewerbsnachteile; er betrifft nur wenige Branchen, Studien sehen Lücken bei Weiterverarbeitern. Änderung liegt bei der EU.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=29', null, 'gemischt', '2026-10-22', false, true, 'blind'),
  (10865, 44, 13, null, 'Staatliche Förderung für Produkte wie E-Autos nur für größtenteils in Europa produzierte Produkte gewähren.', '{4403}', null, 2, 2, null, 'Lenkt geförderte Nachfrage etwa bei E-Autos auf europäische Produktion und mindert so Importdruck; die OECD sieht bei Local-Content-Vorgaben höhere Kosten und Einbußen in anderen Branchen. Ausgestaltung muss EU- und WTO-Recht beachten.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=30', 'https://ideas.repec.org/p/oec/traaab/209-en.html', 'gemischt', '2026-10-22', false, true, 'blind'),
  (10866, 44, 14, null, 'Transatlantische Handelsbeziehungen durch sektorale Abkommen vertiefen, etwa ein Industriezölle-Abkommen', '{4401}', 10839, 2, 1, null, 'Setzt direkt an den US-Zöllen an; ein Industriezoll-Abkommen würde Exporte entlasten. Ergebnis hängt vom Willen der US-Regierung ab, Handelspolitik ist EU-Zuständigkeit; die Verhandlungen 2025 brachten nur begrenzte Senkungen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=52', null, 'offen', '2026-10-22', false, true, 'blind'),
  (10867, 44, 14, null, 'Ausgehandelte und laufende EU-Freihandelsabkommen mit mehreren Staaten zügig abschließen', '{4401}', 10838, 2, 1, null, 'Modellrechnungen (ifo 2025) zeigen, dass Abkommen u. a. mit Mercosur, Indien und ASEAN-Staaten die Exportverluste durch US-Zölle ausgleichen könnten; Zollsätze der USA ändern sie nicht. Abschluss liegt bei der EU und braucht Zustimmung der Partner.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=52', null, 'gemischt', '2026-10-22', false, true, 'blind'),
  (10868, 44, 14, null, 'Partnerschaften bei Rohstoffen und grünen Technologien vor allem mit mittleren Mächten ausbauen', '{4402}', 10840, 2, 2, null, 'Japan senkte nach 2010 mit Partnerschaften und staatlich gestützten Investitionen seine Abhängigkeit von China bei Seltenen Erden von über 90 auf 60–70 %. Partnerschaften ohne Finanzierung brachten in Deutschland bisher kaum Lieferungen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=52', 'https://thenightly.com.au/politics/world/the-new-york-times-how-japan-built-a-rare-earth-supply-chain-without-china-c-20939714', 'gemischt', '2026-10-22', false, true, 'blind'),
  (10869, 44, 14, null, 'Moderne Recyclingmethoden fördern und den gesetzlichen Rahmen dafür ausgestalten', '{4402}', 10842, 1, 2, null, 'Recycling ersetzt langfristig Primärrohstoffe; bei Seltenen Erden liegt die Recyclingquote aber nur bei etwa 1 %, und Rückläufe aus langlebigen Produkten kommen spät. Quoten sind teils EU-rechtlich vorgeprägt.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=41', 'https://www.jyu.fi/en/news/towards-better-autonomy-rare-earth-elements-recycled-from-waste', 'belegt', '2026-10-22', false, true, 'blind'),
  (10870, 44, 14, null, 'Europaweit gegen die Schwemme illegaler Billigprodukte aus China vorgehen', '{4403}', 10843, 1, 2, null, 'Schließt Lücken, über die Kleinsendungen zoll- und kontrollfrei hereinkommen; die EU hat die Abschaffung der 150-Euro-Freigrenze beschlossen. Der Effekt auf heimische Hersteller ist kaum untersucht; Händler weichen etwa auf EU-Lager aus.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=49', null, 'offen', '2026-10-22', false, true, 'blind'),
  (10871, 44, 15, null, 'Zusammenarbeit mit Mercosur, ASEAN und BRICS fördern, wenn sie dem Land dient; WTO reformieren', '{4401}', null, 1, 1, null, 'WTO-Reform und Zusammenarbeit mit weiteren Wirtschaftsräumen können Zollkonflikte entschärfen und Absatzmärkte öffnen; der Text bleibt unbestimmt, und Ergebnisse hängen von vielen anderen Staaten ab.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=95', null, 'offen', '2026-10-22', false, true, 'blind'),
  (10872, 44, 15, null, 'Vorhandene Handelshemmnisse beseitigen', '{4401}', null, 1, 1, null, 'Abbau von Handelshemmnissen kann Exporte erleichtern; der Text nennt weder Partner noch Weg, und gegen US-Zölle hilft eigener Abbau nur über Verhandlungen auf EU-Ebene.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=15', null, 'offen', '2026-10-22', false, true, 'blind'),
  (10873, 44, 15, null, 'Handelsabkommen abschließen, die Rohstofflieferketten sichern', '{4402}', 10840, 2, 2, null, 'Japan senkte nach 2010 mit Partnerschaften und staatlich gestützten Investitionen seine Abhängigkeit von China bei Seltenen Erden von über 90 auf 60–70 %. Partnerschaften ohne Finanzierung brachten in Deutschland bisher kaum Lieferungen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=15', 'https://thenightly.com.au/politics/world/the-new-york-times-how-japan-built-a-rare-earth-supply-chain-without-china-c-20939714', 'gemischt', '2026-10-22', false, true, 'blind'),
  (10874, 44, 15, null, 'CO₂-Grenzausgleich aufheben', '{4403}', null, 0, 1, null, 'Die Abschaffung des CO₂-Grenzausgleichs entlastet Importeure, mindert aber den Schutz heimischer Hersteller vor CO₂-intensiven Importen; zum Ziel trägt sie nicht bei. Änderung nur durch EU-Beschluss.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=15', null, 'gemischt', '2026-10-22', false, true, 'blind'),
  (10875, 44, 16, null, 'Heimische Agrarproduktion vor billigen Importen aus Drittländern mit geringeren Standards schützen', '{4403}', null, 1, 1, null, 'Schutz vor Billigimporten mit geringeren Standards (etwa Spiegelklauseln) kann Agrarbetriebe entlasten; ein Instrument nennt der Text nicht, Handelspolitik ist EU-Zuständigkeit und WTO-rechtlich begrenzt.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=42', null, 'offen', '2026-10-22', false, true, 'blind'),
  (10876, 44, 16, null, 'Höhere gesetzliche Recyclingquoten und Einsatzquoten für wiederverwertete Stoffe', '{4402}', 10842, 1, 2, null, 'Recycling ersetzt langfristig Primärrohstoffe; bei Seltenen Erden liegt die Recyclingquote aber nur bei etwa 1 %, und Rückläufe aus langlebigen Produkten kommen spät. Quoten sind teils EU-rechtlich vorgeprägt.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=35', 'https://www.jyu.fi/en/news/towards-better-autonomy-rare-earth-elements-recycled-from-waste', 'belegt', '2026-10-22', false, true, 'blind'),
  (10877, 44, 16, null, 'Ressourcenschutzgesetz für sparsamen Umgang mit Ressourcen', '{4402}', 10842, 1, 2, null, 'Recycling ersetzt langfristig Primärrohstoffe; bei Seltenen Erden liegt die Recyclingquote aber nur bei etwa 1 %, und Rückläufe aus langlebigen Produkten kommen spät. Quoten sind teils EU-rechtlich vorgeprägt.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=35', 'https://www.jyu.fi/en/news/towards-better-autonomy-rare-earth-elements-recycled-from-waste', 'belegt', '2026-10-22', false, true, 'blind'),
  (10878, 44, 17, null, 'Bundesregierung soll sich in der EU-Handelspolitik gegen unfaire Handelspraktiken der USA zur Wehr setzen', '{4401}', null, 1, 1, null, 'EU-Gegenmaßnahmen trafen 2018 gezielt US-Exporte bei geringem Eigenschaden (Fetzer/Schwarz); dass sie US-Zölle senken, ist nicht belegt, Eskalation droht. Text bleibt unbestimmt, Entscheidung liegt bei der EU.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=14', 'https://www.ifo.de/en/cesifo/node/43044', 'gemischt', '2026-10-22', false, true, 'blind'),
  (10879, 44, 17, null, 'Internationale Abkommen mit Standards, damit heimische Anbieter nicht von Billigproduzenten verdrängt werden', '{4403}', null, 1, 1, null, 'Verbindliche Standards in Abkommen können Billigkonkurrenz aus weniger regulierten Ländern verteuern; der Text nennt weder Partner noch Instrument, Handelspolitik ist EU-Zuständigkeit und braucht Zustimmung der Partnerländer.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=13', null, 'offen', '2026-10-22', false, true, 'blind'),
  (10880, 44, 17, null, 'Handelsabkommen wie das Mercosur-Abkommen ablehnen, die Konkurrenzdruck durch Importe erhöhen', '{4403}', null, 1, 1, null, 'Verhindert zusätzlichen Importdruck auf die Landwirtschaft; das Thünen-Institut erwartet durch Mercosur aber nur Produktionsrückgänge unter 1 % (v. a. Rindfleisch), zugleich entfallen Exportchancen. Entscheidung liegt beim EU-Rat.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=19', 'https://www.topagrar.com/management-und-politik/news/welche-bedeutung-hat-mercosur-fuer-oezdemirs-agrarpolitik-13306578.html', 'belegt', '2026-10-22', false, true, 'blind');

